SELECT mi1.info, n.name, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_1344
WHERE (it2.id IN ('25')) AND (n.name ILIKE '%wa%') AND (rt.role IN ('actress','costume designer','director','miscellaneous crew')) AND (mi1.info IN ('American Sign Language','Arabic','Cantonese','Chinese','Croatian','Finnish','Hebrew','Hindi','History','Italian','Korean','Mandarin','News','Polish','Reality-TV','Romance','Talk-Show','War','Western','Yoruba')) AND (t.production_year >= 1925) AND (t.production_year <= 2015) AND (it1.id IN ('2','3','4')) AND (kt.kind IN ('episode','video movie'));